def patch_workspace_popen(monkeypatch, replacement):
    """Patch common qualified and directly imported Popen lookup styles."""

    workspace_module = importlib.import_module(Workspace.__module__)
    monkeypatch.setattr(subprocess, "Popen", replacement)
    monkeypatch.setattr(workspace_module, "Popen", replacement, raising=False)


def patch_workspace_thread(monkeypatch, replacement):
    """Patch common qualified and directly imported Thread lookup styles."""

    workspace_module = importlib.import_module(Workspace.__module__)
    monkeypatch.setattr(threading, "Thread", replacement)
    monkeypatch.setattr(workspace_module, "Thread", replacement, raising=False)


def patch_workspace_killpg(monkeypatch, replacement):
    """Patch common qualified and directly imported killpg lookup styles."""

    workspace_module = importlib.import_module(Workspace.__module__)
    monkeypatch.setattr(os, "killpg", replacement)
    monkeypatch.setattr(workspace_module, "killpg", replacement, raising=False)


def test_task_1_creates_and_atomically_replaces_files(tmp_path):
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))

    assert workspace.write_file("new.txt", "one") == "wrote new.txt"
    assert (tmp_path / "new.txt").read_text(encoding="utf-8") == "one"
    assert workspace.write_file("new.txt", "two") == "wrote new.txt"
    assert (tmp_path / "new.txt").read_text(encoding="utf-8") == "two"


def test_task_1_requires_inspection_before_overwriting(tmp_path):
    (tmp_path / "existing.txt").write_text("old", encoding="utf-8")
    workspace = Workspace(ToolPolicy(tmp_path, allow_writes=True))

    try:
        workspace.write_file("existing.txt", "new")
    except AgentError as error:
        assert "must be read" in str(error)
    else:
        assert False, "expected an uninspected overwrite to be rejected"
    assert (tmp_path / "existing.txt").read_text(encoding="utf-8") == "old"


