@pytest.mark.parametrize("tool", ["write_file", "edit_file"])
@pytest.mark.parametrize("external_change", ["replace", "delete"])
def test_task_2_revalidates_an_existing_file_after_confirmation(
    tmp_path, tool, external_change
):
    path = tmp_path / "answer.py"
    path.write_text("ANSWER = 41\n", encoding="utf-8")

    def change_during_confirmation(action):
        if external_change == "replace":
            path.write_text("ANSWER = 99\n", encoding="utf-8")
        else:
            path.unlink()
        return True

    workspace = Workspace(
        ToolPolicy(tmp_path, allow_writes=True),
        confirm_tool=change_during_confirmation,
    )
    workspace.read_file("answer.py")

    action = (
        ToolAction(
            "write_file",
            {"path": "answer.py", "content": "ANSWER = 42\n"},
        )
        if tool == "write_file"
        else ToolAction(
            "edit_file",
            {"path": "answer.py", "old": "41", "new": "42"},
        )
    )

    result = workspace.execute(action)

    assert result == "error: file changed since it was read; read it again"
    if external_change == "replace":
        assert path.read_text(encoding="utf-8") == "ANSWER = 99\n"
