def test_task_4_successful_compaction_is_durable_and_model_visible(tmp_path):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser", kind="task")
    for number in range(6):
        _append_context_turn(session, number)
    original_events = session.events
    expected_summary = _summary_payload(changed_files=[], validation=[])
    summary_inputs = []

    def summarize(messages):
        summary_inputs.append([dict(message) for message in messages])
        return json.dumps(expected_summary)

    manager = ContextManager(_encode_context_messages, policy=_context_policy())

    window = manager.prepare(session, "system", summarize=summarize)

    attempts = _events_of_type(session, "summary_attempt")
    compactions = _events_of_type(session, "compaction")
    assert len(summary_inputs) == len(attempts) == len(compactions) == 1
    assert "exactly this schema" in summary_inputs[0][0]["content"]
    assert summary_inputs[0][-1]["content"].startswith("Return the bounded")
    assert attempts[0].data == {
        "status": "accepted",
        "response": json.dumps(expected_summary),
        "error": None,
    }
    event = compactions[0]
    assert event.data["summary"] == expected_summary
    assert event.data["strategy"] == "model"
    assert event.data["fallback_reason"] is None
    assert event.data["covered_through_event_id"] in {
        item.id for item in original_events
    }
    assert event.data["input_tokens_before"] > event.data["input_tokens_after"]
    assert window.followed_compaction is True
    assert window.compaction_event_id == event.id
    assert tuple(session.events[: len(original_events)]) == original_events
    rendered = "\n".join(message["content"] for message in window.messages)
    assert expected_summary["facts"][0] in rendered
    assert expected_summary["next_step"] in rendered


@pytest.mark.parametrize(
    ("failure", "attempt_status"),
    [
        ("malformed", "invalid"),
        ("missing-field", "invalid"),
        ("extra-field", "invalid"),
        ("wrong-type", "invalid"),
        ("exception", "error"),
    ],
)
def test_task_4_invalid_summaries_get_one_attempt_then_fall_back(
    tmp_path, failure, attempt_status
):
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix the parser", kind="task")
    for number in range(6):
        _append_context_turn(session, number)
    calls = 0

    def summarize(_messages):
        nonlocal calls
        calls += 1
        if failure == "exception":
            raise RuntimeError("summary backend unavailable")
        if failure == "malformed":
            return "not JSON"
        candidate = _summary_payload()
        if failure == "missing-field":
            candidate.pop("facts")
        elif failure == "extra-field":
            candidate["confidence"] = 1
        else:
            candidate["constraints"] = "not a list"
        return json.dumps(candidate)

    manager = ContextManager(_encode_context_messages, policy=_context_policy())

    window = manager.prepare(session, "system", summarize=summarize)

    attempts = _events_of_type(session, "summary_attempt")
    compactions = _events_of_type(session, "compaction")
    assert calls == len(attempts) == len(compactions) == 1
    assert attempts[0].data["status"] == attempt_status
    event = compactions[0]
    assert event.data["strategy"] == "deterministic"
    assert isinstance(event.data["fallback_reason"], str)
    assert event.data["fallback_reason"]
    assert set(event.data["summary"]) == set(_summary_payload())
    assert isinstance(event.data["summary"]["goal"], str)
    assert isinstance(event.data["summary"]["next_step"], str)
    assert all(
        isinstance(event.data["summary"][field], list)
        for field in (
            "constraints",
            "facts",
            "changed_files",
            "validation",
            "failed_approaches",
        )
    )
    assert window.followed_compaction is True
    assert len(window.token_ids) <= manager.policy.working_tokens


