class _ContextCache:
    def __init__(self):
        self.offset = 0

    def rewind(self, count):
        if count < 0 or count > self.offset:
            raise ValueError("invalid rewind")
        self.offset -= count

    def release(self):
        pass


class _ContextArray:
    def __init__(self, values):
        self.values = list(values)

    def __getitem__(self, _key):
        return self


class _ContextLogits:
    def __init__(self, token):
        self.token = token

    def __getitem__(self, _key):
        return self


class _ContextScalar:
    def __init__(self, value):
        self.value = value

    def item(self):
        return self.value


class _ContextTokenizer:
    eos_token_id = 0

    def apply_chat_template(self, messages, **_kwargs):
        return "|".join(
            f"{message['role']}:{message['content']}" for message in messages
        )

    def encode(self, prompt, **_kwargs):
        return [(ord(character) % 251) + 1 for character in prompt]

    def decode(self, tokens):
        return ",".join(map(str, tokens))


class _ContextModel:
    def __call__(self, tokens, _offset, caches):
        for cache in caches:
            cache.offset += len(tokens.values)
        return _ContextLogits(7)


def _install_context_mlx(monkeypatch):
    mlx = ModuleType("mlx")
    core = ModuleType("mlx.core")
    core.array = _ContextArray
    core.argmax = lambda logits, axis: _ContextScalar(logits.token)
    mlx.core = core
    monkeypatch.setitem(sys.modules, "mlx", mlx)
    monkeypatch.setitem(sys.modules, "mlx.core", core)


def test_task_5_compaction_reconciles_the_warm_cache_and_records_metrics(
    tmp_path, monkeypatch
):
    _install_context_mlx(monkeypatch)
    session = memory_session(tmp_path, "test-model")
    session.append("user_message", content="fix parser", kind="task")
    for number in range(6):
        _append_context_turn(session, number)
    caches = [_ContextCache(), _ContextCache()]
    generation = GenerationSession(
        _ContextModel(),
        _ContextTokenizer(),
        lambda: caches,
        max_tokens=1,
    )
    generation(session.messages("system"))
    manager = ContextManager(
        generation.encode_messages,
        policy=_context_policy(
            max_tokens=800,
            reserve_tokens=120,
            summary_max_tokens=320,
            max_tool_result_tokens=180,
        ),
    )
    window = manager.prepare(
        session,
        "system",
        summarize=lambda _messages: json.dumps(
            _summary_payload(
                constraints=[],
                validation=[],
                failed_approaches=[],
            )
        ),
    )

    warm_response = generation(list(window.messages))
    cold_caches = [_ContextCache(), _ContextCache()]
    cold_generation = GenerationSession(
        _ContextModel(),
        _ContextTokenizer(),
        lambda: cold_caches,
        max_tokens=1,
    )
    cold_response = cold_generation(list(window.messages))

    stats = generation.last_stats
    assert warm_response == cold_response
    assert stats.input_tokens == len(window.token_ids)
    assert stats.reused_tokens > 0
    assert stats.rewound_tokens > 0
    assert stats.prefilled_tokens > 0
    assert stats.cold_start is False
    assert stats.latency_seconds is not None
    assert stats.latency_seconds >= 0
